/**
 * Redis Client for Caching and Idempotency
 *
 * Provides Redis-backed caching for:
 * - Entitlements caching (reduce database load)
 * - Pioneer action idempotency (distributed deduplication)
 * - Attribution fingerprint lookups
 *
 * Includes graceful degradation to in-memory when Redis unavailable
 *
 * Production Features:
 * - Exponential backoff with jitter (up to 20 retries)
 * - TCP keepalive (5s) to prevent silent drops
 * - Application-level ping (60s) to keep connection alive
 * - Key namespacing for logical separation
 */
import { createLogger, LogLevel } from "@vreko/contracts";
import { createClient } from "redis";
import { isSocketTimeoutError } from "./redis-factory.js";
import { getMetricsCollector } from "./redis-metrics.js";
const logger = createLogger({ name: "redis-client", level: LogLevel.INFO });
// Key prefix for platform caching operations
const KEY_PREFIX = "cache:";
// Redis client instance
let redisClient = null;
let redisAvailable = false;
let initializationPromise = null;
// Metrics collector for this client
const metricsCollector = getMetricsCollector(KEY_PREFIX);
/**
 * Initialize Redis client connection with production-ready configuration
 */
export async function initializeRedis() {
    if (initializationPromise) {
        return initializationPromise;
    }
    initializationPromise = (async () => {
        const redisUrl = process.env.REDIS_URL;
        if (!redisUrl) {
            logger.warn("REDIS_URL not configured - using in-memory fallback for caching");
            return;
        }
        try {
            // Production-ready Redis client configuration
            redisClient = createClient({
                url: redisUrl,
                socket: {
                    // Connection timeout - how long to wait for initial connection
                    connectTimeout: 10000, // 10s
                    // TCP keepalive - prevents silent connection drops
                    keepAlive: 5000, // 5s
                    // Reconnection strategy with exponential backoff + jitter
                    reconnectStrategy: (retries, cause) => {
                        // Don't reconnect on socket timeout - indicates a different issue
                        // (e.g., firewall, network partition) that won't be fixed by reconnecting
                        if (isSocketTimeoutError(cause)) {
                            logger.warn("Redis socket timeout - not reconnecting", { cause: cause?.message });
                            return false;
                        }
                        // Give up after 20 retries (increased from 3)
                        if (retries > 20) {
                            logger.error("Redis max retries exceeded", { retries, cause: cause?.message });
                            return new Error("Redis connection failed");
                        }
                        // Exponential backoff with jitter
                        // 100ms, 200ms, 400ms, 800ms, ... max 30s
                        const baseDelay = Math.min(2 ** retries * 100, 30000);
                        const jitter = Math.floor(Math.random() * 200);
                        return baseDelay + jitter;
                    },
                },
                // Application-level ping to keep connection alive
                pingInterval: 60000, // 60s
            });
            redisClient.on("error", (err) => {
                // Don't log ECONNRESET as warning - it's expected during reconnection
                if (err.message.includes("ECONNRESET") || err.message.includes("ECONNREFUSED")) {
                    logger.debug("Redis connection error (will reconnect)", { error: err.message });
                }
                else {
                    logger.warn("Redis client error", { error: err.message });
                }
                redisAvailable = false;
                metricsCollector.recordError(err);
            });
            redisClient.on("connect", () => {
                redisAvailable = true;
                metricsCollector.resetReconnectCount();
                if (process.env.NODE_ENV !== "production") {
                    logger.info("Redis connected for platform caching");
                }
            });
            redisClient.on("ready", () => {
                redisAvailable = true;
                logger.debug("Redis client ready for platform caching");
            });
            redisClient.on("reconnecting", () => {
                metricsCollector.recordReconnect();
                logger.debug("Redis reconnecting for platform caching");
            });
            await redisClient.connect();
            redisAvailable = true;
            if (process.env.NODE_ENV !== "production") {
                logger.info("✅ Redis client initialized for platform caching with production config");
            }
        }
        catch (error) {
            logger.error("Redis initialization failed", {
                error: error instanceof Error ? error.message : String(error),
            });
            redisAvailable = false;
        }
    })();
    return initializationPromise;
}
/**
 * Get value from Redis cache
 */
export async function getCache(key) {
    await initializeRedis();
    if (!redisAvailable || !redisClient) {
        return null;
    }
    try {
        const value = await redisClient.get(key);
        if (!value) {
            return null;
        }
        return JSON.parse(value);
    }
    catch (error) {
        logger.error("Redis GET failed", { key, error });
        return null;
    }
}
/**
 * Set value in Redis cache with optional TTL
 */
export async function setCache(key, value, ttlSeconds) {
    await initializeRedis();
    if (!redisAvailable || !redisClient) {
        return false;
    }
    try {
        const serialized = JSON.stringify(value);
        if (ttlSeconds) {
            await redisClient.set(key, serialized, { EX: ttlSeconds });
        }
        else {
            await redisClient.set(key, serialized);
        }
        return true;
    }
    catch (error) {
        logger.error("Redis SET failed", { key, error });
        return false;
    }
}
/**
 * Delete value from Redis cache
 */
export async function deleteCache(key) {
    await initializeRedis();
    if (!redisAvailable || !redisClient) {
        return false;
    }
    try {
        await redisClient.del(key);
        return true;
    }
    catch (error) {
        logger.error("Redis DEL failed", { key, error });
        return false;
    }
}
/**
 * Check if key exists in Redis
 */
export async function hasCache(key) {
    await initializeRedis();
    if (!redisAvailable || !redisClient) {
        return false;
    }
    try {
        const exists = await redisClient.exists(key);
        return exists === 1;
    }
    catch (error) {
        logger.error("Redis EXISTS failed", { key, error });
        return false;
    }
}
/**
 * Set if not exists (atomic operation for idempotency)
 */
export async function setNX(key, value, ttlSeconds) {
    await initializeRedis();
    if (!redisAvailable || !redisClient) {
        return false;
    }
    try {
        const serialized = JSON.stringify(value);
        const result = ttlSeconds
            ? await redisClient.set(key, serialized, { NX: true, EX: ttlSeconds })
            : await redisClient.set(key, serialized, { NX: true });
        return result === "OK";
    }
    catch (error) {
        logger.error("Redis SETNX failed", { key, error });
        return false;
    }
}
/**
 * Get multiple keys at once (batch operation)
 */
export async function mGet(keys) {
    if (keys.length === 0) {
        return [];
    }
    await initializeRedis();
    if (!redisAvailable || !redisClient) {
        return keys.map(() => null);
    }
    try {
        const values = await redisClient.mGet(keys);
        return values.map((v) => (v ? JSON.parse(v) : null));
    }
    catch (error) {
        logger.error("Redis MGET failed", { keys, error });
        return keys.map(() => null);
    }
}
/**
 * Close Redis connection
 */
export async function closeRedis() {
    if (redisClient) {
        try {
            await redisClient.quit();
            logger.info("Redis connection closed");
        }
        catch (error) {
            logger.error("Error closing Redis connection", { error });
        }
        redisClient = null;
        redisAvailable = false;
    }
}
/**
 * Check if Redis is available
 */
export function isRedisAvailable() {
    return redisAvailable;
}
/**
 * Get Redis client (for advanced operations)
 */
export function getRedisClient() {
    return redisClient;
}
/**
 * Get metrics for this Redis client
 */
export async function getRedisMetrics() {
    if (!redisClient) {
        return {
            isConnected: false,
            latency: null,
            lastError: "Redis client not initialized",
            reconnectAttempts: 0,
        };
    }
    return metricsCollector.collect(redisClient);
}
// Lazy initialization - Redis is initialized on first cache access, not module load
// This ensures environment variables (e.g., from Doppler) are available
