/**
 * Redis Metrics Collection
 *
 * Provides utilities for monitoring Redis connection health,
 * latency, and reconnection statistics.
 *
 * @module @vreko/platform/cache
 */
/**
 * Latency thresholds for health status
 */
export const LATENCY_THRESHOLDS = {
    /** Under 100ms is healthy */
    healthy: 100,
    /** Under 500ms is degraded */
    degraded: 500,
};
/**
 * Track Redis metrics for a client
 */
export class RedisMetricsCollector {
    reconnectAttempts = 0;
    lastSuccessAt = null;
    lastErrorAt = null;
    lastError = null;
    keyPrefix;
    constructor(keyPrefix = "") {
        this.keyPrefix = keyPrefix;
    }
    /**
     * Record a successful operation
     */
    recordSuccess() {
        this.lastSuccessAt = Date.now();
    }
    /**
     * Record an error
     */
    recordError(error) {
        this.lastErrorAt = Date.now();
        this.lastError = error.message;
    }
    /**
     * Record a reconnection attempt
     */
    recordReconnect() {
        this.reconnectAttempts++;
    }
    /**
     * Reset reconnection counter (after successful connection)
     */
    resetReconnectCount() {
        this.reconnectAttempts = 0;
    }
    /**
     * Measure Redis latency using PING command
     */
    async measureLatency(client) {
        if (!client || !client.isReady) {
            return null;
        }
        try {
            const start = Date.now();
            await client.ping();
            const latency = Date.now() - start;
            this.recordSuccess();
            return latency;
        }
        catch (error) {
            this.recordError(error);
            return null;
        }
    }
    /**
     * Collect comprehensive metrics
     */
    async collect(client) {
        const isConnected = client?.isReady ?? false;
        const isOpen = client?.isOpen ?? false;
        const latency = await this.measureLatency(client);
        // Determine health status
        let status;
        let message;
        if (!isConnected) {
            status = "unhealthy";
            message = "Redis client not connected";
        }
        else if (latency === null) {
            status = "unhealthy";
            message = "Redis PING failed";
        }
        else if (latency < LATENCY_THRESHOLDS.healthy) {
            status = "healthy";
            message = `Redis latency: ${latency}ms`;
        }
        else if (latency < LATENCY_THRESHOLDS.degraded) {
            status = "degraded";
            message = `Redis latency elevated: ${latency}ms`;
        }
        else {
            status = "unhealthy";
            message = `Redis latency too high: ${latency}ms`;
        }
        return {
            isConnected,
            isOpen,
            latency,
            status,
            message,
            lastSuccessAt: this.lastSuccessAt,
            lastErrorAt: this.lastErrorAt,
            lastError: this.lastError,
            reconnectAttempts: this.reconnectAttempts,
            keyPrefix: this.keyPrefix,
        };
    }
    /**
     * Get current reconnection attempt count
     */
    getReconnectAttempts() {
        return this.reconnectAttempts;
    }
}
/**
 * Global metrics collectors by key prefix
 */
const metricsCollectors = new Map();
/**
 * Get or create a metrics collector for a key prefix
 */
export function getMetricsCollector(keyPrefix = "") {
    let collector = metricsCollectors.get(keyPrefix);
    if (!collector) {
        collector = new RedisMetricsCollector(keyPrefix);
        metricsCollectors.set(keyPrefix, collector);
    }
    return collector;
}
/**
 * Collect metrics from all registered collectors
 */
export async function collectAllMetrics(clients) {
    const results = new Map();
    for (const [keyPrefix, client] of clients) {
        const collector = getMetricsCollector(keyPrefix);
        const metrics = await collector.collect(client);
        results.set(keyPrefix, metrics);
    }
    return results;
}
/**
 * Check if Redis metrics indicate a healthy state
 */
export function isHealthy(metrics) {
    return metrics.status === "healthy" || metrics.status === "degraded";
}
/**
 * Get a summary of Redis health for logging/monitoring
 */
export function getHealthSummary(metrics) {
    return `[${metrics.keyPrefix || "default"}] ${metrics.status.toUpperCase()}: ${metrics.message}`;
}
