/**
 * Redis Client Factory - Production-Ready Configuration
 *
 * Provides a unified factory for creating Redis clients with:
 * - Exponential backoff with jitter for reconnection
 * - Connection keepalive to prevent silent drops
 * - Application-level ping interval
 * - Key namespacing for logical separation
 *
 * @module @vreko/platform/cache
 */
import { createLogger, LogLevel } from "@vreko/contracts";
import { createClient } from "redis";
const logger = createLogger({ name: "redis-factory", level: LogLevel.INFO });
/**
 * Check if an error is a socket timeout error
 * Socket timeouts indicate network/firewall issues, not transient Redis failures
 */
export function isSocketTimeoutError(cause) {
    if (!cause) {
        return false;
    }
    return cause?.name === "SocketTimeoutError" || cause?.message?.includes("socket timeout");
}
/**
 * Default Redis client options optimized for production
 */
export const DEFAULT_REDIS_OPTIONS = {
    keyPrefix: "",
    maxRetries: 20,
    pingInterval: 60000,
    connectTimeout: 10000,
    keepAlive: 5000,
};
/**
 * Create a production-ready Redis client with optimal configuration
 *
 * Features:
 * - Exponential backoff with jitter for reconnection
 * - Connection keepalive to prevent silent drops
 * - Application-level ping interval
 * - Proper error handling and logging
 * - Key namespacing utility for logical separation
 *
 * @example
 * ```typescript
 * // Create client for auth module
 * const authRedis = createRedisClient({
 *   pingInterval: 60000,
 *   onConnect: () => process.stdout.write('Auth Redis connected'),
 * });
 *
 * await authRedis.connect();
 *
 * // Use key namespacing for logical separation
 * await authRedis.set(withKeyPrefix('auth:', 'session:123'), data);
 * ```
 */
export function createRedisClient(options = {}) {
    const config = { ...DEFAULT_REDIS_OPTIONS, ...options };
    const redisUrl = process.env.REDIS_URL;
    if (!redisUrl) {
        logger.warn("REDIS_URL not configured - Redis client will not be available");
        return null;
    }
    // Validate URL format
    if (!redisUrl.startsWith("redis://") && !redisUrl.startsWith("rediss://")) {
        logger.error("Invalid REDIS_URL format", {
            error: "REDIS_URL must start with 'redis://' or 'rediss://' protocol",
            example: "redis://localhost:6379",
        });
        return null;
    }
    const client = createClient({
        url: redisUrl,
        socket: {
            // Connection timeout - how long to wait for initial connection
            connectTimeout: config.connectTimeout,
            // TCP keepalive - prevents silent connection drops
            keepAlive: config.keepAlive,
            // Reconnection strategy with exponential backoff + jitter
            reconnectStrategy: (retries, cause) => {
                // Don't reconnect on socket timeout - indicates a different issue
                // (e.g., firewall, network partition) that won't be fixed by reconnecting
                if (isSocketTimeoutError(cause)) {
                    logger.warn("Redis socket timeout - not reconnecting", { cause: cause?.message });
                    return false;
                }
                // Give up after max retries
                if (retries > config.maxRetries) {
                    logger.error("Redis max retries exceeded", {
                        retries,
                        maxRetries: config.maxRetries,
                        cause: cause?.message,
                    });
                    return new Error(`Redis connection failed after ${config.maxRetries} retries`);
                }
                // Exponential backoff with jitter
                // 100ms, 200ms, 400ms, 800ms, 1600ms, 3200ms, ... max 30s
                const baseDelay = Math.min(2 ** retries * 100, 30000);
                const jitter = Math.floor(Math.random() * 200);
                const delay = baseDelay + jitter;
                logger.debug("Redis reconnecting", { retries, delay, nextRetryIn: `${delay}ms` });
                return delay;
            },
        },
        // Application-level ping to keep connection alive
        pingInterval: config.pingInterval,
    });
    // Set up event handlers
    client.on("error", (err) => {
        // Don't log ECONNRESET as error - it's expected during reconnection
        if (err.message.includes("ECONNRESET") || err.message.includes("ECONNREFUSED")) {
            logger.debug("Redis connection error (will reconnect)", { error: err.message });
        }
        else {
            logger.warn("Redis client error", { error: err.message });
        }
        options.onDisconnect?.(err);
    });
    client.on("connect", () => {
        logger.debug("Redis connection initiated");
    });
    client.on("ready", () => {
        logger.info("Redis client ready", { keyPrefix: config.keyPrefix || "none" });
        options.onConnect?.();
    });
    client.on("reconnecting", () => {
        logger.debug("Redis client reconnecting");
        options.onReconnecting?.();
    });
    client.on("end", () => {
        logger.debug("Redis connection closed");
    });
    return client;
}
/**
 * Utility function to add key prefix for logical namespace separation
 *
 * @param prefix - The namespace prefix (e.g., 'auth:', 'cache:', 'ratelimit:')
 * @param key - The key to prefix
 * @returns The prefixed key
 *
 * @example
 * ```typescript
 * const key = withKeyPrefix('auth:', 'session:123'); // 'auth:session:123'
 * ```
 */
export function withKeyPrefix(prefix, key) {
    return `${prefix}${key}`;
}
/**
 * Predefined key prefixes for consistent namespacing
 */
export const REDIS_KEY_PREFIXES = {
    AUTH: "auth:",
    AUTH_RATE_LIMIT: "auth:ratelimit:",
    CACHE: "cache:",
    ENTITLEMENTS: "cache:entitlements:",
    WAITLIST: "cache:waitlist:",
    RATE_LIMIT: "ratelimit:",
    IDEMPOTENCY: "idempotency:",
    SESSION: "session:",
};
